public object FfiConverterTypeRequestHandler: FfiConverter<RequestHandler, Long> {
    internal val handleMap = UniffiHandleMap<RequestHandler>()

    override fun lower(value: RequestHandler): Long {
        if (value is RequestHandlerImpl) {
