    fun `onRequest`(`channel`: kotlin.String, `handler`: RequestHandler)
    
    fun `peers`(): List<FfiPeer>
    
    suspend fun `publish`(`topic`: kotlin.String, `body`: kotlin.ByteArray)
    
    fun `removePeer`(`id`: kotlin.String): kotlin.Boolean
    
    suspend fun `request`(`to`: kotlin.String, `channel`: kotlin.String, `body`: kotlin.ByteArray): kotlin.ByteArray
    
    suspend fun `send`(`to`: kotlin.String, `channel`: kotlin.String, `body`: kotlin.ByteArray): FfiLink
    
    suspend fun `sendFile`(`to`: kotlin.String, `path`: kotlin.String): FfiFileOffer
    
    suspend fun `shutdown`()
    
    suspend fun `spaceDelete`(`space`: kotlin.String, `key`: kotlin.String)
    
    suspend fun `spaceGet`(`space`: kotlin.String, `key`: kotlin.String): kotlin.ByteArray?
    
    suspend fun `spaceKeys`(`space`: kotlin.String): List<kotlin.String>
    
    suspend fun `spaceSet`(`space`: kotlin.String, `key`: kotlin.String, `value`: kotlin.ByteArray)
    
    /**
     * Close the forward to `peer`, if there is one.
     */
    suspend fun `stopForward`(`peer`: kotlin.String): kotlin.Boolean
    
    suspend fun `subscribe`(`topic`: kotlin.String)
    
    /**
     * Lease a tunnel and return a wg-quick config to hand to the platform VPN API.
     */
    suspend fun `tunnelConfig`(): kotlin.String
    
    companion object
}

