/**
 * @suppress
 */
public object FfiConverterTypeTethersysNode: FfiConverter<TethersysNode, Long> {
    override fun lower(value: TethersysNode): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): TethersysNode {
        return TethersysNode(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): TethersysNode {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: TethersysNode) = 8UL

    override fun write(value: TethersysNode, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



