    {
        

        companion object
    }
    
    data class Paired(
        val `peer`: kotlin.String, 
        val `name`: kotlin.String) : FfiEvent()
        
    {
        

        companion object
    }
    
    data class Message(
        val `from`: kotlin.String, 
        val `channel`: kotlin.String, 
        val `body`: kotlin.ByteArray, 
        val `fromMailbox`: kotlin.Boolean) : FfiEvent()
        
    {
        

