    {
        

        companion object
    }
    
    data class SpaceChanged(
        val `space`: kotlin.String, 
        val `key`: kotlin.String, 
        val `author`: kotlin.String, 
        val `deleted`: kotlin.Boolean) : FfiEvent()
        
    {
        

        companion object
    }
    
    data class Server(
        val `connected`: kotlin.Boolean, 
        val `detail`: kotlin.String) : FfiEvent()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiEvent : FfiConverterRustBuffer<FfiEvent>{
    override fun read(buf: ByteBuffer): FfiEvent {
        return when(buf.getInt()) {
            1 -> FfiEvent.Connected(
                FfiConverterString.read(buf),
                FfiConverterTypeFfiLink.read(buf),
                )
            2 -> FfiEvent.LinkChanged(
                FfiConverterString.read(buf),
                FfiConverterTypeFfiLink.read(buf),
                FfiConverterULong.read(buf),
                )
            3 -> FfiEvent.Paired(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> FfiEvent.Message(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterBoolean.read(buf),
                )
            5 -> FfiEvent.FileOffered(
                FfiConverterTypeFfiFileOffer.read(buf),
                )
            6 -> FfiEvent.FileProgress(
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            7 -> FfiEvent.FileDone(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> FfiEvent.FileFailed(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> FfiEvent.TopicMessage(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            10 -> FfiEvent.SpaceChanged(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            11 -> FfiEvent.Server(
                FfiConverterBoolean.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiEvent): ULong = when(value) {
        is FfiEvent.Connected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
                + FfiConverterTypeFfiLink.allocationSize(value.`link`)
            )
        }
        is FfiEvent.LinkChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
                + FfiConverterTypeFfiLink.allocationSize(value.`link`)
                + FfiConverterULong.allocationSize(value.`rttMs`)
            )
        }
        is FfiEvent.Paired -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`peer`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is FfiEvent.Message -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`from`)
                + FfiConverterString.allocationSize(value.`channel`)
                + FfiConverterByteArray.allocationSize(value.`body`)
                + FfiConverterBoolean.allocationSize(value.`fromMailbox`)
            )
        }
        is FfiEvent.FileOffered -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeFfiFileOffer.allocationSize(value.`offer`)
            )
        }
        is FfiEvent.FileProgress -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`hash`)
                + FfiConverterULong.allocationSize(value.`bytes`)
                + FfiConverterULong.allocationSize(value.`total`)
            )
        }
        is FfiEvent.FileDone -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`hash`)
                + FfiConverterString.allocationSize(value.`path`)
            )
        }
        is FfiEvent.FileFailed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`hash`)
                + FfiConverterString.allocationSize(value.`error`)
            )
        }
        is FfiEvent.TopicMessage -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`topic`)
                + FfiConverterString.allocationSize(value.`author`)
                + FfiConverterByteArray.allocationSize(value.`body`)
            )
        }
        is FfiEvent.SpaceChanged -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`space`)
                + FfiConverterString.allocationSize(value.`key`)
                + FfiConverterString.allocationSize(value.`author`)
                + FfiConverterBoolean.allocationSize(value.`deleted`)
            )
        }
        is FfiEvent.Server -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`connected`)
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: FfiEvent, buf: ByteBuffer) {
        when(value) {
            is FfiEvent.Connected -> {
                buf.putInt(1)
                FfiConverterString.write(value.`peer`, buf)
                FfiConverterTypeFfiLink.write(value.`link`, buf)
                Unit
            }
            is FfiEvent.LinkChanged -> {
                buf.putInt(2)
                FfiConverterString.write(value.`peer`, buf)
                FfiConverterTypeFfiLink.write(value.`link`, buf)
                FfiConverterULong.write(value.`rttMs`, buf)
                Unit
            }
            is FfiEvent.Paired -> {
                buf.putInt(3)
                FfiConverterString.write(value.`peer`, buf)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
            is FfiEvent.Message -> {
                buf.putInt(4)
                FfiConverterString.write(value.`from`, buf)
                FfiConverterString.write(value.`channel`, buf)
                FfiConverterByteArray.write(value.`body`, buf)
                FfiConverterBoolean.write(value.`fromMailbox`, buf)
                Unit
            }
            is FfiEvent.FileOffered -> {
                buf.putInt(5)
                FfiConverterTypeFfiFileOffer.write(value.`offer`, buf)
                Unit
            }
            is FfiEvent.FileProgress -> {
                buf.putInt(6)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterULong.write(value.`bytes`, buf)
                FfiConverterULong.write(value.`total`, buf)
                Unit
            }
            is FfiEvent.FileDone -> {
                buf.putInt(7)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterString.write(value.`path`, buf)
                Unit
            }
            is FfiEvent.FileFailed -> {
                buf.putInt(8)
                FfiConverterString.write(value.`hash`, buf)
                FfiConverterString.write(value.`error`, buf)
                Unit
            }
            is FfiEvent.TopicMessage -> {
                buf.putInt(9)
                FfiConverterString.write(value.`topic`, buf)
                FfiConverterString.write(value.`author`, buf)
                FfiConverterByteArray.write(value.`body`, buf)
                Unit
            }
            is FfiEvent.SpaceChanged -> {
                buf.putInt(10)
                FfiConverterString.write(value.`space`, buf)
                FfiConverterString.write(value.`key`, buf)
                FfiConverterString.write(value.`author`, buf)
                FfiConverterBoolean.write(value.`deleted`, buf)
                Unit
            }
            is FfiEvent.Server -> {
                buf.putInt(11)
                FfiConverterBoolean.write(value.`connected`, buf)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






enum class FfiLink {
    
    DIRECT,
    RELAYED,
    QUEUED;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeFfiLink: FfiConverterRustBuffer<FfiLink> {
    override fun read(buf: ByteBuffer) = try {
        FfiLink.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: FfiLink) = 4UL

    override fun write(value: FfiLink, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






